#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const readJsonl = (file) => fs.readFileSync(file, 'utf8')
  .split(/\r?\n/)
  .map((line) => line.trim())
  .filter(Boolean)
  .map(JSON.parse);
const writeJsonl = (file, rows) => fs.writeFileSync(file, `${rows.map((row) => JSON.stringify(row)).join('\n')}\n`);
const write = (file, content) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content.endsWith('\n') ? content : `${content}\n`);
};

const mappingFile = 'data/project/estate-lens-mappings.jsonl';
const trackMapFile = 'data/estates/track-map.jsonl';
const specs = {"opportunity-zones-value-capture":{"phases":["P4-dual-use-platform-state","P5-reindustrializing-market-maker-state"],"stages":["C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A3-selector","A4-public-market-maker","A6-paper-architect","A8-residual-rights-holder","A10-adjudicator"]},"metro-station-tod-sweep":{"phases":["P3-innovation-bridge","P4-dual-use-platform-state","P5-reindustrializing-market-maker-state"],"stages":["C1-agenda-formation","C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A1-convener","A2-translator","A3-selector","A4-public-market-maker","A6-paper-architect","A8-residual-rights-holder","A9-legitimizer","A10-adjudicator"]},"chips-act-fab-siting":{"phases":["P5-reindustrializing-market-maker-state"],"stages":["C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A3-selector","A4-public-market-maker","A6-paper-architect","A8-residual-rights-holder","A10-adjudicator"]},"stadium-arena-public-finance":{"phases":["P3-innovation-bridge","P4-dual-use-platform-state","P5-reindustrializing-market-maker-state"],"stages":["C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A3-selector","A4-public-market-maker","A6-paper-architect","A8-residual-rights-holder","A10-adjudicator"]},"tif-district-value-capture":{"phases":["P3-innovation-bridge","P4-dual-use-platform-state","P5-reindustrializing-market-maker-state"],"stages":["C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A3-selector","A4-public-market-maker","A6-paper-architect","A8-residual-rights-holder","A10-adjudicator"]},"oge278-revolving-door-routers":{"phases":["P4-dual-use-platform-state","P5-reindustrializing-market-maker-state"],"stages":["C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A3-selector","A4-public-market-maker","A5-personnel-router","A6-paper-architect","A8-residual-rights-holder","A10-adjudicator"]},"defense-accelerator-fund-rosters":{"phases":["P3-innovation-bridge","P4-dual-use-platform-state","P5-reindustrializing-market-maker-state"],"stages":["C1-agenda-formation","C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A1-convener","A2-translator","A3-selector","A4-public-market-maker","A5-personnel-router","A6-paper-architect","A8-residual-rights-holder","A9-legitimizer","A10-adjudicator"]},"regulatory-revolving-doors":{"phases":["P4-dual-use-platform-state","P5-reindustrializing-market-maker-state"],"stages":["C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A3-selector","A4-public-market-maker","A5-personnel-router","A6-paper-architect","A8-residual-rights-holder","A10-adjudicator"]},"congressional-disclosure-crossings":{"phases":["P5-reindustrializing-market-maker-state"],"stages":["C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A3-selector","A4-public-market-maker","A6-paper-architect","A8-residual-rights-holder","A10-adjudicator"]},"state-officeholder-land-contract-crossings":{"phases":["P4-dual-use-platform-state","P5-reindustrializing-market-maker-state"],"stages":["C2-option-set-formation","C3-public-conversion","C4-control-architecture","C6-residual-value","C7-reversibility-and-counterpower"],"archetypes":["A3-selector","A4-public-market-maker","A5-personnel-router","A6-paper-architect","A8-residual-rights-holder","A10-adjudicator"]}};
const trackMap = readJsonl(trackMapFile);
const managedTrackIds = new Set(Object.keys(specs));
const retained = readJsonl(mappingFile).filter(
  (row) => row.object_kind !== 'research_track' || !managedTrackIds.has(row.object_id)
);
const added = [];

for (const entry of [...trackMap].sort((a, b) => a.track_id.localeCompare(b.track_id))) {
  const spec = specs[entry.track_id];
  if (!spec) throw new Error(`missing mapping specification for ${entry.track_id}`);
  for (const estateId of [entry.primary_estate_id, ...(entry.related_estate_ids ?? [])]) {
    added.push({
      mapping_id: `map-track-${entry.track_id}-${estateId.replace(/-estate$/, '')}`,
      estate_id: estateId,
      object_kind: 'research_track',
      object_id: entry.track_id,
      phase_ids: spec.phases,
      conversion_stage_ids: spec.stages,
      archetype_ids: spec.archetypes,
      basis_refs: [`data/research-tracks/${entry.track_id}/harness.json`, trackMapFile],
      mapping_status: 'explicit_object_mapping',
      graph_effect: 'none',
      conclusion_generated: false,
    });
  }
}

if (added.length !== 29) throw new Error(`expected 29 research-track mappings, found ${added.length}`);
for (const row of added) {
  if (!fs.existsSync(row.basis_refs[0])) throw new Error(`missing harness ${row.basis_refs[0]}`);
}
const rows = [...retained, ...added];
const mappingIds = new Set(rows.map((row) => row.mapping_id));
const mappingKeys = new Set(rows.map((row) => `${row.estate_id}|${row.object_kind}|${row.object_id}`));
if (mappingIds.size !== rows.length) throw new Error('duplicate mapping_id');
if (mappingKeys.size !== rows.length) throw new Error('duplicate estate/object mapping key');

writeJsonl(mappingFile, rows);
write('test/estate-lens-audit.test.js', "import assert from 'node:assert/strict';\nimport fs from 'node:fs';\n\nconst readJson = (path) => JSON.parse(fs.readFileSync(path, 'utf8'));\nconst readJsonl = (path) => fs.readFileSync(path, 'utf8')\n  .split(/\\r?\\n/)\n  .map((line) => line.trim())\n  .filter(Boolean)\n  .map(JSON.parse);\n\nconst manifest = readJson('build/core-thesis/estate-lens-audit-manifest.json');\nconst objects = manifest.estates.flatMap((estate) =>\n  readJson(`build/core-thesis/estate-lens-audit/estates/${estate.estate_id}.json`).objects\n);\nconst mappings = readJsonl('data/project/estate-lens-mappings.jsonl');\nconst trackMap = readJsonl('data/estates/track-map.jsonl');\n\nassert.equal(manifest.counts.estates, 24);\nassert.equal(objects.filter((x) => x.object_kind === 'estate_root').length, 24);\nassert.ok(objects.some((x) =>\n  x.object_kind === 'case'\n  && x.object_id === 'anduril-access-ownership'\n  && x.mapping_state === 'explicit_mapped'\n));\nassert.ok(objects.some((x) => x.object_kind === 'source_route' && x.mapping_state === 'known_unmapped'));\nassert.ok(objects.some((x) => x.ukraine_war_shock.state !== 'not_reached'));\n\nconst expectedTrackKeys = new Set(trackMap.flatMap((row) => [\n  `${row.primary_estate_id}|${row.track_id}`,\n  ...(row.related_estate_ids ?? []).map((estateId) => `${estateId}|${row.track_id}`),\n]));\nconst mappedTrackKeys = new Set(objects\n  .filter((x) => x.object_kind === 'research_track' && x.mapping_state === 'explicit_mapped')\n  .map((x) => `${x.estate_id}|${x.object_id}`));\n\nassert.deepEqual(\n  [...mappedTrackKeys].sort(),\n  [...expectedTrackKeys].sort(),\n  'every declared research-track membership must have an explicit object mapping'\n);\nassert.equal(mappedTrackKeys.size, 29);\n\nassert.equal(new Set(mappings.map((x) => x.mapping_id)).size, mappings.length, 'mapping_id values must be unique');\nassert.equal(\n  new Set(mappings.map((x) => `${x.estate_id}|${x.object_kind}|${x.object_id}`)).size,\n  mappings.length,\n  'estate/object mapping keys must be unique'\n);\nfor (const row of mappings.filter((x) => x.object_kind === 'research_track')) {\n  assert.deepEqual(\n    row.basis_refs,\n    [`data/research-tracks/${row.object_id}/harness.json`, 'data/estates/track-map.jsonl'],\n    `${row.mapping_id}: research-track mapping basis`\n  );\n  assert.equal(fs.existsSync(row.basis_refs[0]), true, `${row.mapping_id}: missing harness`);\n  assert.equal(row.mapping_status, 'explicit_object_mapping', row.mapping_id);\n  assert.equal(row.graph_effect, 'none', row.mapping_id);\n  assert.equal(row.conclusion_generated, false, row.mapping_id);\n}\n\nassert.equal(manifest.graph_effect, 'none');\nassert.equal(manifest.conclusion_generated, false);\nassert.equal(manifest.estate_completion_claimed, false);\n\nconsole.log('estate-lens-audit.test: OK');\n");
write('docs/milestones/m04c-h0-research-track-mappings.md', "# M-04C.H0 · Explicit research-track mappings\n\nThe first orbital mapping pass replaces inherited-only routing for every currently declared research-track membership with a checked-in object-level mapping.\n\n```text\n10 research tracks\n29 estate memberships\n29 explicit research-track mappings\n0 research-track memberships left inherited-only\n```\n\n## Basis\n\nEach mapping is grounded only in:\n\n- the track's own `research-track-harness@1` question, scan, denominator, source adapters, coverage discipline, and epistemic contract; and\n- the checked-in primary/related estate assignment in `data/estates/track-map.jsonl`.\n\nThe pass does not claim that a search was executed, a crossing exists, a public-private conversion occurred, or any actor coordinated, influenced, captured, profited improperly, or committed wrongdoing. Most harnesses remain `status: scaffold`, and their coverage seeds remain `not_searched`.\n\n## Mapped tracks\n\n- Opportunity Zone value-capture formation\n- Transit station-area TOD formation sweep\n- CHIPS-Act fab and data-center siting formation\n- Stadium and arena public-finance capture\n- Tax-increment-financing district value capture\n- OGE-278 senior-appointee revolving-door routers\n- Defense-tech accelerator and fund roster routers\n- Regulatory revolving-door routers\n- Congressional disclosure and federal money-stream crossings\n- State officeholder land and contract crossings\n\n## Conversion grammar\n\nThe pass maps the questions the harnesses are designed to test:\n\n```text\nbounded denominator and option set\n→ public designation, appointment, approval, contract, or subsidy\n→ ownership, vehicle, land, governance, or control architecture\n→ money, capital, value, or residual-rights question\n→ explicit nulls, unsuccessful paths, ethics, adjudication, recovery, and controls\n```\n\nPlace-formation tracks also preserve planning and agenda formation where the harness explicitly asks about plans, entitlement, designation, public commitment, and intermediary governance. Person-router and disclosure-crossing tracks preserve personnel-routing, exact entity, temporal, ethics, and null-control questions without treating routing scores or exact overlaps as allegations.\n\n## Regression\n\nThe estate-lens audit regression now derives the expected research-track membership set directly from `data/estates/track-map.jsonl` and refuses:\n\n- any declared track membership that is not `explicit_mapped`;\n- duplicate mapping IDs;\n- duplicate estate/object mapping keys;\n- a research-track mapping without the exact harness and track-map basis;\n- graph effects or generated conclusions.\n\n## Next pass\n\nThe next H0 orbit maps the twenty declared estate slices and their 53 primary/related memberships. Those rows require slice-specific phase and conversion-stage review rather than automatic inheritance from the parent track.\n\n```text\npromotes_to: candidate_only\ngraph_effect: none\nconclusion_generated: false\nestate_completion_claimed: false\n```\n");
console.log(JSON.stringify({ mappings: rows.length, research_track_mappings: added.length }, null, 2));
